-- The scan batches a player has validated, so that sending the same batch again writes nothing.
-- The batch identifier is generated by the client; it is recorded in the transaction that writes
-- the batch's copies.
CREATE TABLE scan_batch
(
    user_id      VARCHAR(50) NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    id           UUID        NOT NULL,
    validated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, id)
);
